{ 
   "name": "Priya Nair", 
   "email": "priya.nair@example.com", 
   "requested_date": "next Thursday the 14th" 
 }

def dedupe_preserve_order(lst): 
     out = [] 
     seen = set() 
     for item in lst: 
         try: 
             if item in seen: 
                 continue 
             seen.add(item) 
             out.append(item) 
         except TypeError: 
             # unhashable item — fall back to O(n) equality check 
             found = False 
             for x in out: 
                 if x == item: 
                     found = True 
                     break 
             if not found: 
                 out.append(item) 
     return out
